// Firebase configuration for the customer app (project logistics-93b9f).
//
// Normally generated by `flutterfire configure`; maintained by hand here with
// the same shape. Values mirror android/app/google-services.json — they are
// client identifiers, not secrets. Only Android is configured; add iOS options
// (and GoogleService-Info.plist) when the iOS app is registered in Firebase.

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart' show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('DefaultFirebaseOptions are not configured for web.');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not configured for ios - '
          'register the iOS app in Firebase and add its options.',
        );
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not supported for this platform.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyCICfkmDo5PqVYbjfQdC6IQGArhcM1CsGk',
    appId: '1:461709902538:android:23fdca11efc22d6f876a33',
    messagingSenderId: '461709902538',
    projectId: 'logistics-93b9f',
    storageBucket: 'logistics-93b9f.firebasestorage.app',
  );
}
